{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a map of the ruined royal city.",
      "visual_description": "A windswept hilltop overlook at dusk; ink-stained coat flaps as a brass compass spins over a parchment showing collapsed spires and a distant bridge.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of obvious traps ahead.",
      "visual_description": "Close-up of an oil lamp with a single glowing eye in its flame, casting orange light across the cartographer's worried face.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox is wound up for scouting.",
      "visual_description": "A small clockwork fox with blue glass eyes sits on a stone wall while a gloved hand turns its key-wind tail; gears tick audibly in the dawn mist.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver emerges from a rain puddle.",
      "visual_description": "A figure in a clear diving helmet rises from a shallow puddle reflecting the broken skyline, coat shimmering with fragments of city light.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The team approaches the castle gates.",
      "visual_description": "Massive iron-banded gates hang crooked under tattered royal banners; the tin fox creeps ahead while the cartographer crouches behind rubble.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "The lamp insists the gates are bait.",
      "visual_description": "The oracle lamp's flame leans sideways as if pointing away from the gates, its eye narrowed; faint runes glow on the gate's keystone.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "An armored patrol clatters past unseen.",
      "visual_description": "Empty suits of patrol armor march in lockstep down a cracked avenue; the team hides in a doorway, the diver pressed flat against a tall mirror.",
      "characters": ["glass_diver", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "They find the sleeping tax collector slumped at a checkpoint.",
      "visual_description": "A plump official snores atop a ledger pillow, stamped papers stuck to his sleeves, a half-drunk cup of tea cooling beside an unattended toll bar.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Rumors of a winged beast rumble in the distance.",
      "visual_description": "Far across the city, a vast silhouette circles a cursed tower; the cartographer points at it on her map while the lamp's eye dims with worry.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "The tin fox finds a hidden alley route.",
      "visual_description": "The clockwork fox stands at the mouth of a narrow alley, tail flicking, paw raised toward a faint chalk arrow on a soot-stained wall.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "The glass diver slips through a shop window.",
      "visual_description": "Coat rippling with reflected lights, the diver dives headfirst into a cracked storefront pane as if it were water, ripples spreading across the glass.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "Frightened townspeople peek from shuttered windows.",
      "visual_description": "Wide, fearful eyes glimmer behind warped shutters along a narrow lane; the tin fox tips its head up at them while the cartographer raises an empty, peaceful hand.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "A magic door blocks the path to the cursed tower.",
      "visual_description": "An obsidian door covered in shifting silver glyphs hums in a ruined courtyard; the oracle lamp's flame stretches toward one specific glyph.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The glass diver swims through the door's polished face.",
      "visual_description": "The diver disappears into the obsidian door as into dark water, helmet rim leaving a glowing ripple while the fox watches, ears perked.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "Inside the tower, the captive is found chained beneath a banner.",
      "visual_description": "A torchlit chamber draped with faded royal banners; the diver kneels beside a slumped captive, releasing iron cuffs while the lamp lights the corner.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "Alarms wake every checkpoint except one.",
      "visual_description": "Bells swing wildly atop crumbled towers; in the foreground, the tax collector keeps snoring, drool puddling on a stamped writ as the fox darts past his boots.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The team races for the bridge as patrol armor closes in.",
      "visual_description": "A long stone bridge arcs over a misted chasm; the cartographer leads at a sprint, the diver supporting the rescued captive, lamp swinging, fox bounding ahead.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Safe across, they look back at the burning city.",
      "visual_description": "On the far bank at sunrise, the cartographer folds her map, the diver's coat still glittering with city reflections, the lamp's eye finally soft, the tin fox seated calmly at her feet.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    }
  ]
}

